#!/usr/bin/env python3
"""NEON HEROES — single-file project package.

Run: python NEON_HEROES_FULL_PROJECT.py [output_dir]
The embedded project archive is extracted into output_dir.
"""
import base64, io, os, sys, zipfile
DATA = """"""

def main():
    target = sys.argv[1] if len(sys.argv) > 1 else "neon-heroes-FULL-PROJECT"
    os.makedirs(target, exist_ok=True)
    raw = base64.b64decode(DATA)
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        z.extractall(target)
    print(f"NEON HEROES extracted to: {os.path.abspath(target)}")
    print(f"Files restored: {len(z.namelist())}")

if __name__ == "__main__":
    main()
